    margin: 0;
}

.sidebar-btn {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    width: 100%;
    padding: 0.65rem 1.25rem;
    border: none;
    background: transparent;
    font-size: 0.95rem;
    color: #495057;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
    text-align: left;
}

.sidebar-btn:hover {
    background: #e9ecef;
