}

/* ===== Content Area ===== */

.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    max-width: 800px;
    position: relative;
}

.settings-section h2 {
    font-size: 1.5rem;
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.section-description {
    color: #6c757d;
    margin-bottom: 1.75rem;
}

.subsection-title {
    font-size: 1rem;
    font-weight: 600;
