    margin-bottom: 0.75rem;
}

/* ===== Form Controls ===== */

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.35rem;
    font-size: 0.9rem;
}

.button-group {
    display: flex;
    gap: 0.75rem;
