}

/* ===== Toggle Switches ===== */

.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.toggle-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.85rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-item:last-child {
    border-bottom: none;
}

.toggle-label {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.toggle-label span:first-child {
    font-weight: 500;
    font-size: 0.95rem;
}

.toggle-label .text-muted {
    font-size: 0.8rem;
}

.switch {
    position: relative;
    display: inline-block;
    width: 46px;
    height: 26px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    transition: 0.2s;
    border-radius: 26px;
}

.slider::before {
    position: absolute;
    content: "";
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.2s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(20px);
}

