.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-theme-light .preview-header {
    background: #f8f9fa;
}

.preview-theme-light .preview-btn {
    background: #0d6efd;
    color: #fff;
}

.preview-theme-light .preview-badge {
    background: #cfe2ff;
