.preview-theme-system .preview-header {
    background: rgba(248, 249, 250, 0.85);
}

.preview-theme-system .preview-btn {
    background: #0d6efd;
    color: #fff;
}

.preview-theme-system .preview-badge {
    background: #cfe2ff;
    color: #084298;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-compact .preview-header {
    padding: 0.4rem 0.75rem;
}

.preview-compact .preview-body {
    padding: 0.5rem 0.75rem;
    gap: 0.5rem;
}

.preview-compact .preview-btn {
    padding: 0.2rem 0.6rem;
}

/* ===== Toast ===== */

.toast-notification {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border-radius: 0.5rem;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
    font-size: 0.9rem;
    z-index: 1100;
    animation: toast-slide-in 0.25s ease-out;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

.toast-close {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    opacity: 0.7;
    line-height: 1;
    color: inherit;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes toast-slide-in {
    from {
        transform: translateY(1rem);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

/* ===== Loading ===== */

.loading-spinner {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 200px;
