@page "/settings"
@using sv_1ec142beee5b45ceb1deee2741a17825.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar" aria-label="Settings sections">
        <h3 class="sidebar-title">Settings</h3>
        <ul class="sidebar-nav">
            @foreach (var section in _sections)
            {
                <li>
                    <button class="sidebar-btn @(section == _activeSection ? "active" : "")"
                            @onclick="() => SetActiveSection(section)">
                        <span class="sidebar-icon">@GetSectionIcon(section)</span>
                        @section
                    </button>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastMessage is not null)
        {
            <div class="toast-notification @(_toastIsError ? "toast-error" : "toast-success")" role="alert">
                <span>@_toastMessage</span>
                <button class="toast-close" @onclick="DismissToast">&times;</button>
            </div>
        }
    </div>
</div>

@* ---------- PROFILE SECTION ---------- *@

@{
    RenderFragment RenderProfileSection() =>
        @<section class="settings-section">
            <h2>Profile</h2>
            <p class="section-description">Manage your personal information and public profile.</p>

            <div class="avatar-area">
                @if (!string.IsNullOrWhiteSpace(_profileDisplayName))
                {
                    <div class="avatar-preview">
                        <img src="@_profileAvatarUrl" alt="Avatar preview" />
                    </div>
                }
                <div class="avatar-url-display">
                    <label>Avatar URL</label>
                    <span class="text-muted">@_profileAvatarUrl</span>
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control"
                       @bind="_profileDisplayName" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" class="form-control"
                       @bind="_profileEmail" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4"
                          @bind="_profileBio" @bind:event="oninput"></textarea>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges" disabled="@_saving">
                    Discard Changes
                </button>
            </div>
        </section>;
}

@* ---------- NOTIFICATIONS SECTION ---------- *@

@{
    RenderFragment RenderNotificationsSection() =>
        @<section class="settings-section">
            <h2>Notifications</h2>
            <p class="section-description">Choose how you want to be notified.</p>

            <div class="toggle-group">
                <div class="toggle-item">
                    <label class="toggle-label">
                        <span>Email Notifications</span>
                        <span class="text-muted">Receive notifications via email</span>
                    </label>
                    <label class="switch">
                        <input type="checkbox" @bind="_notifEmail" />
                        <span class="slider"></span>
                    </label>
                </div>
                <div class="toggle-item">
                    <label class="toggle-label">
                        <span>Push Notifications</span>
                        <span class="text-muted">Receive push notifications in your browser</span>
                    </label>
                    <label class="switch">
                        <input type="checkbox" @bind="_notifPush" />
                        <span class="slider"></span>
                    </label>
                </div>
                <div class="toggle-item">
                    <label class="toggle-label">
                        <span>Weekly Digest</span>
                        <span class="text-muted">Get a weekly summary of activity</span>
                    </label>
                    <label class="switch">
                        <input type="checkbox" @bind="_notifWeeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>

            <h4 class="subsection-title">Muted Channels</h4>
            <p class="text-muted">Uncheck a channel to unmute it.</p>

            @if (_allChannels.Count > 0)
            {
                <div class="channel-list">
                    @foreach (var channel in _allChannels)
                    {
                        var ch = channel;
                        <label class="channel-item">
                            <input type="checkbox" checked="@_mutedChannels.Contains(ch)"
                                   @onchange="e => ToggleMutedChannel(ch, (bool)e.Value!)" />
                            <span>@ch</span>
                        </label>
                    }
                </div>
            }
            else
            {
                <p class="text-muted fst-italic">No channels available.</p>
            }

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveNotificationPrefs" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save Preferences
                </button>
            </div>
        </section>;
}

@* ---------- SECURITY SECTION ---------- *@

@{
    RenderFragment RenderSecuritySection() =>
        @<section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Manage your password, two-factor authentication, and active sessions.</p>

            <!-- Change Password Panel -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>🔑 Change Password</span>
                    <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">▶</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" class="form-control"
                                   @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" class="form-control"
                                   @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm New Password</label>
                            <input id="confirmPwd" type="password" class="form-control"
                                   @bind="_confirmPassword" />
                        </div>
                        @if (_passwordError is not null)
                        {
                            <div class="alert alert-danger">@_passwordError</div>
                        }
                        <button class="btn btn-warning" @onclick="UpdatePassword" disabled="@_saving">
                            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="toggle-group mt-3">
                <div class="toggle-item">
                    <label class="toggle-label">
                        <span>Two-Factor Authentication</span>
                        <span class="status-indicator @(_twoFactorEnabled ? "status-on" : "status-off")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </label>
                    <label class="switch">
                        <input type="checkbox" @bind="_twoFactorEnabled" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>

            @if (_securitySettings?.LastPasswordChange is not null)
            {
                <p class="text-muted mt-2">
                    Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </p>
            }

            <!-- Active Sessions -->
            <h4 class="subsection-title mt-4">Active Sessions</h4>
            @if (_securitySettings?.Sessions.Count > 0)
            {
                <div class="table-responsive">
                    <table class="table table-hover sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != _securitySettings.Sessions[0])
                                        {
                                            <button class="btn btn-sm btn-outline-danger"
                                                    @onclick="() => ConfirmRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="badge bg-success">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p class="text-muted fst-italic">No active sessions.</p>
            }

            <!-- Revoke Confirmation Dialog -->
            @if (_sessionToRevoke is not null)
            {
                <div class="modal-backdrop" @onclick="CancelRevoke"></div>
                <div class="confirmation-dialog" role="dialog" aria-modal="true">
                    <h5>Revoke Session</h5>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                    <div class="button-group">
                        <button class="btn btn-danger" @onclick="RevokeConfirmedSession" disabled="@_saving">
                            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Revoke
                        </button>
                        <button class="btn btn-outline-secondary" @onclick="CancelRevoke" disabled="@_saving">Cancel</button>
                    </div>
                </div>
            }
        </section>;
}

@* ---------- APPEARANCE SECTION ---------- *@

@{
    RenderFragment RenderAppearanceSection() =>
        @<section class="settings-section">
            <h2>Appearance</h2>
            <p class="section-description">Customize how the application looks and feels.</p>

            <h4 class="subsection-title">Theme</h4>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    var t = theme;
                    <label class="radio-item @(_appearanceTheme == t ? "selected" : "")">
                        <input type="radio" name="theme" value="@t"
                               checked="@(_appearanceTheme == t)"
                               @onchange="() => _appearanceTheme = t" />
                        <span>@t</span>
                    </label>
                }
            </div>

            <h4 class="subsection-title">Font Size</h4>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    var s = size;
                    <label class="radio-item @(_appearanceFontSize == s ? "selected" : "")">
                        <input type="radio" name="fontSize" value="@s"
                               checked="@(_appearanceFontSize == s)"
                               @onchange="() => _appearanceFontSize = s" />
                        <span>@s</span>
                    </label>
                }
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" class="form-select" @bind="_appearanceLanguage">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                    <option value="pt">Português</option>
                </select>
            </div>

            <div class="toggle-group">
                <div class="toggle-item">
                    <label class="toggle-label">
                        <span>Compact Mode</span>
                        <span class="text-muted">Reduce spacing and padding throughout the UI</span>
                    </label>
                    <label class="switch">
                        <input type="checkbox" @bind="_appearanceCompactMode" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>

            <!-- Live Preview -->
            <h4 class="subsection-title">Preview</h4>
            <div class="live-preview @GetPreviewClasses()">
                <div class="preview-header">
                    <strong>Sample Card</strong>
                </div>
                <div class="preview-body">
                    <p>This is a preview of your selected appearance settings.</p>
                    <button class="preview-btn">Sample Button</button>
                    <span class="preview-badge">Badge</span>
                </div>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save
                </button>
            </div>
        </section>;
}

@code {
    private static readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;
    private bool _saving;
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // Profile state
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // Notification state
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifWeeklyDigest;
    private List<string> _allChannels = [];
    private HashSet<string> _mutedChannels = [];

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private string _appearanceTheme = "System";
    private string _appearanceFontSize = "Medium";
    private string _appearanceLanguage = "en";
    private bool _appearanceCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData(_activeSection);
        _loading = false;
    }

    private async Task SetActiveSection(string section)
    {
        if (section == _activeSection) return;
        _activeSection = section;
        _loading = true;
        DismissToast();
        await LoadSectionData(section);
        _loading = false;
    }

    private async Task LoadSectionData(string section)
    {
        switch (section)
        {
            case "Profile":
                var profile = await SettingsService.GetProfileAsync();
                _savedProfile = profile;
                ApplyProfile(profile);
                break;

            case "Notifications":
                var prefs = await SettingsService.GetNotificationPrefsAsync();
                _notifEmail = prefs.EmailNotifications;
                _notifPush = prefs.PushNotifications;
                _notifWeeklyDigest = prefs.WeeklyDigest;
                _mutedChannels = [.. prefs.MutedChannels];
                // Ensure muted channels also appear in the full channel list
                if (_allChannels.Count == 0)
                {
                    _allChannels = ["general", "announcements", "engineering", "design", "marketing", "random"];
                }
                foreach (var ch in prefs.MutedChannels.Where(c => !_allChannels.Contains(c)))
                {
                    _allChannels.Add(ch);
                }
                break;

            case "Security":
                _securitySettings = await SettingsService.GetSecuritySettingsAsync();
                _twoFactorEnabled = _securitySettings.TwoFactorEnabled;
                _passwordPanelOpen = false;
                _currentPassword = "";
                _newPassword = "";
                _confirmPassword = "";
                _passwordError = null;
                _sessionToRevoke = null;
                break;

            case "Appearance":
                var appearance = await SettingsService.GetAppearanceAsync();
                _appearanceTheme = appearance.Theme;
                _appearanceFontSize = appearance.FontSize;
                _appearanceLanguage = appearance.Language;
                _appearanceCompactMode = appearance.CompactMode;
                break;
        }
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    // ---------- Profile actions ----------

    private async Task SaveProfile()
    {
        _saving = true;
        try
        {
            var updated = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
            await SettingsService.SaveProfileAsync(updated);
            _savedProfile = updated;
            ShowToast("Profile saved successfully.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to save profile: {ex.Message}", isError: true);
        }
        finally
        {
            _saving = false;
        }
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // ---------- Notification actions ----------

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotificationPrefs()
    {
        _saving = true;
        try
        {
            var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifWeeklyDigest, [.. _mutedChannels]);
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            ShowToast("Notification preferences saved.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to save preferences: {ex.Message}", isError: true);
        }
        finally
        {
            _saving = false;
        }
    }

    // ---------- Security actions ----------

    private async Task UpdatePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword) ||
            string.IsNullOrWhiteSpace(_confirmPassword))
        {
            _passwordError = "All password fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _passwordPanelOpen = false;
            ShowToast("Password updated successfully.");
        }
        catch (Exception ex)
        {
            _passwordError = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeConfirmedSession()
    {
        if (_sessionToRevoke is null) return;

        _saving = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            // Reload security data
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _sessionToRevoke = null;
            ShowToast("Session revoked.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to revoke session: {ex.Message}", isError: true);
        }
        finally
        {
            _saving = false;
        }
    }

    // ---------- Appearance actions ----------

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_appearanceTheme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_appearanceFontSize.ToLowerInvariant()}");
        if (_appearanceCompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        try
        {
            var settings = new AppearanceSettings(_appearanceTheme, _appearanceFontSize, _appearanceLanguage, _appearanceCompactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            ShowToast("Appearance settings saved.");
        }
        catch (Exception ex)
        {
            ShowToast($"Failed to save appearance: {ex.Message}", isError: true);
        }
        finally
        {
            _saving = false;
        }
    }

    // ---------- Toast helpers ----------

    private void ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastMessage = message;
        _toastIsError = isError;

        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _ = Task.Run(async () =>
        {
            await Task.Delay(4000, token);
            if (!token.IsCancellationRequested)
            {
                await InvokeAsync(() =>
                {
                    _toastMessage = null;
                    StateHasChanged();
                });
            }
        }, token);
    }

    private void DismissToast()
    {
        _toastCts?.Cancel();
        _toastMessage = null;
    }

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

/* ===== Layout ===== */

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 3.5rem);
    gap: 0;
}

/* ===== Sidebar ===== */

.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #6c757d;
}

.sidebar-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar-btn {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    width: 100%;
    padding: 0.65rem 1.25rem;
    border: none;
    background: transparent;
    font-size: 0.95rem;
    color: #495057;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
    text-align: left;
}

.sidebar-btn:hover {
    background: #e9ecef;
    color: #212529;
}

.sidebar-btn.active {
    background: #0d6efd;
    color: #fff;
    font-weight: 500;
}

.sidebar-icon {
    font-size: 1.1rem;
    width: 1.5rem;
    text-align: center;
}

/* ===== Content Area ===== */

.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    max-width: 800px;
    position: relative;
}

.settings-section h2 {
    font-size: 1.5rem;
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.section-description {
    color: #6c757d;
    margin-bottom: 1.75rem;
}

.subsection-title {
    font-size: 1rem;
    font-weight: 600;
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
}

/* ===== Form Controls ===== */

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.35rem;
    font-size: 0.9rem;
}

.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* ===== Avatar ===== */

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1.25rem;
    margin-bottom: 1.75rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
}

.avatar-preview {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid #dee2e6;
    flex-shrink: 0;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-url-display label {
    font-weight: 500;
    font-size: 0.85rem;
    display: block;
    margin-bottom: 0.15rem;
}

.avatar-url-display .text-muted {
    font-size: 0.8rem;
    word-break: break-all;
}

/* ===== Toggle Switches ===== */

.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.toggle-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.85rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-item:last-child {
    border-bottom: none;
}

.toggle-label {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
}

.toggle-label span:first-child {
    font-weight: 500;
    font-size: 0.95rem;
}

.toggle-label .text-muted {
    font-size: 0.8rem;
}

.switch {
    position: relative;
    display: inline-block;
    width: 46px;
    height: 26px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    transition: 0.2s;
    border-radius: 26px;
}

.slider::before {
    position: absolute;
    content: "";
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.2s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(20px);
}

